    @Override
    public DungeonLevel goDown() throws IOException, InterruptedException, ParseException {
    	return new DungeonLevel9();
    }

    @Override
    public DungeonLevel goUp() throws IOException, InterruptedException, ParseException {
        return new DungeonLevel7();
    }

    public int[][] getMap() {
        return map;
    }

    public static int getMapWidth() {
        return MAP_WIDTH;
    }

    public static int getMapHeight() {
        return MAP_HEIGHT;
    }

    public int getDungeonLevelNumber() {
        return DUNGEON_LEVEL;
    }

    // Removed redundant getSpecialLocation override to use base implementation in DungeonLevel

    @Override
    public List<? extends MapEntity> getEntities() {
        // TODO: Add entities for level 8
        return Collections.emptyList();
    }

    // Debug: helper method to print map numeric markers (>1) and their coordinates for developers.
    private void printNumberCoordinates() {
        for (int y = 0; y < map.length; y++) {
            for (int x = 0; x < map[y].length; x++) {
                int value = map[y][x];
                if (value > 1) {
                    System.out.println("Level: " + DUNGEON_LEVEL + " Number: " + value + " at (" + x + ", " + y + ")");
                }
            }
        }
    }
